          for g in range(0,min(4*f+2,q)+1):
           for S2 in range(0,k+1):
            out.append((n,l,k,q,e,f,g,S2))
    return sorted(set(out))
names="n ℓ k q e f g 2S".split()
def J_patterns(caps):
    cells=build(caps); bot=min(cells)
    rank=lambda c:sum(c); byrank=defaultdict(list)
    for c in cells: byrank[rank(c)].append(c)
    leq=lambda a,b: all(x<=y for x,y in zip(a,b))
    covered=defaultdict(int)
    for r in sorted(byrank):
        if r+1 in byrank:
            for y in byrank[r+1]:
                covered[y]=sum(1 for x in byrank[r] if leq(x,y))
    J=[c for c in cells if covered[c]==1]
    pats=set(frozenset(names[i] for i in range(8) if c[i]>bot[i]) for c in J)
    return len(cells), len(J), pats
base=None
for caps in [(3,3,1,3,1),(4,4,2,4,1),(4,4,2,6,2),(5,5,2,6,2)]:
    nc,nj,p=J_patterns(caps)
    if base is None: base=p
    print(caps,"cells",nc,"J",nj,"patterns",len(p),"same-as-base" if p==base else ("NEW:"+str(p-base)+" LOST:"+str(base-p)))
print("the 15 patterns:", sorted(map(sorted,base),key=len))

# particle-hole on p shell: LS term counts of p^k for k=0..6
def terms(l,k):
    orbs=[(ml,ms) for ml in range(-l,l+1) for ms in (1,-1)]
    W=defaultdict(int)
    for occ in combinations(range(len(orbs)),k):
        ML=sum(orbs[i][0] for i in occ); MS=sum(orbs[i][1] for i in occ)
        W[(ML,MS)]+=1
    # peel terms
    cnt=0
    W=dict(W)
    while any(v>0 for v in W.values()):
        ML=max(m for (m,s),v in W.items() if v>0)
        MS=max(s for (m,s),v in W.items() if v>0 and m==ML)
        for m in range(-ML,ML+1):
            for s in range(-MS,MS+1,2):
                W[(m,s)]-=1
        cnt+=1
    return cnt
seq=[terms(1,k) for k in range(0,7)]
print("terms(p^k), k=0..6:", seq, " symmetric:", seq==seq[::-1])
